def apply(root):
 prepared=[]
 for name, spec in PLAN.items():
  path=root/name
  data=path.read_bytes(); actual=hashlib.sha256(data).hexdigest()
  if actual==spec["after_sha256"]:continue
  if actual!=spec["before_sha256"]:raise SystemExit("source identity mismatch: "+name)
  text=data.decode()
  for old,new in spec["edits"]:
   if text.count(old)!=1:raise SystemExit("ambiguous boundary: "+name)
   text=text.replace(old,new,1)
  out=text.encode()
  if hashlib.sha256(out).hexdigest()!=spec["after_sha256"]:raise SystemExit("result identity mismatch: "+name)
  prepared.append((path,out))
 for path,data in prepared:path.write_bytes(data)
 return len(prepared)
